-- 1. Structure : tables, clés primaires et étrangères, contraintes
CREATE TABLE "accounts_user" ("password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "id" char(32) NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL UNIQUE, "display_name" varchar(40) NOT NULL UNIQUE, "role" varchar(20) NOT NULL, "preferred_language" varchar(5) NOT NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "date_joined" datetime NOT NULL, "deleted_at" datetime NULL, "anonymised_at" datetime NULL, "accepted_terms_at" datetime NULL, "marketing_consent" bool NOT NULL, CONSTRAINT "user_anonymised_implies_deleted" CHECK (("anonymised_at" IS NULL OR "deleted_at" IS NOT NULL)));
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "axes_accessattempt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "get_data" text NOT NULL, "post_data" text NOT NULL, "failures_since_start" integer unsigned NOT NULL CHECK ("failures_since_start" >= 0));
CREATE TABLE "axes_accessfailurelog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "locked_out" bool NOT NULL);
CREATE TABLE "axes_accesslog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "logout_time" datetime NULL, "session_hash" varchar(64) NOT NULL);
CREATE TABLE "catalog_category" ("id" char(32) NOT NULL PRIMARY KEY, "slug" varchar(60) NOT NULL UNIQUE, "position" smallint unsigned NOT NULL CHECK ("position" >= 0), "is_active" bool NOT NULL, "parent_id" char(32) NULL REFERENCES "catalog_category" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "category_no_self_parent" CHECK (NOT ("parent_id" = ("id") AND "parent_id" IS NOT NULL)));
CREATE TABLE "catalog_categorytranslation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(5) NOT NULL, "name" varchar(80) NOT NULL, "category_id" char(32) NOT NULL REFERENCES "catalog_category" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_category_language" UNIQUE ("category_id", "language"));
CREATE TABLE "catalog_merchant" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(120) NOT NULL, "slug" varchar(120) NOT NULL UNIQUE, "country" varchar(2) NOT NULL, "website" varchar(300) NOT NULL, "vat_number" varchar(20) NOT NULL, "is_local_independent" bool NOT NULL, "is_verified" bool NOT NULL, "created_at" datetime NOT NULL, "brand_color" varchar(7) NOT NULL, "logo" varchar(100) NOT NULL, "address" varchar(200) NOT NULL, "city" varchar(80) NOT NULL, "latitude" decimal NULL, "longitude" decimal NULL, "osm_id" bigint NULL UNIQUE, "shop_type" varchar(30) NOT NULL, CONSTRAINT "merchant_local_implies_be" CHECK ((NOT "is_local_independent" OR "country" = 'BE')), CONSTRAINT "merchant_vat_implies_be" CHECK (("vat_number" = '' OR "country" = 'BE')));
CREATE TABLE "deals_alert" ("id" char(32) NOT NULL PRIMARY KEY, "keyword" varchar(80) NOT NULL, "max_price" decimal NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "last_notified_at" datetime NULL, "category_id" char(32) NULL REFERENCES "catalog_category" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "alert_max_price_positive" CHECK (("max_price" IS NULL OR "max_price" > '0')), CONSTRAINT "uniq_alert_per_user_criteria" UNIQUE ("user_id", "keyword", "category_id"));
CREATE TABLE "deals_alertmatch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_priority" bool NOT NULL, "available_at" datetime NOT NULL, "notified_at" datetime NULL, "created_at" datetime NOT NULL, "alert_id" char(32) NOT NULL REFERENCES "deals_alert" ("id") DEFERRABLE INITIALLY DEFERRED, "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_alert_match" UNIQUE ("alert_id", "deal_id"));
CREATE TABLE "deals_comment" ("id" char(32) NOT NULL PRIMARY KEY, "body" text NOT NULL, "is_verified_purchase" bool NOT NULL, "created_at" datetime NOT NULL, "deleted_at" datetime NULL, "author_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, "language" varchar(5) NOT NULL);
CREATE TABLE "deals_commenttranslation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(5) NOT NULL, "body" text NOT NULL, "is_machine_translated" bool NOT NULL, "comment_id" char(32) NOT NULL REFERENCES "deals_comment" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_comment_language" UNIQUE ("comment_id", "language"));
CREATE TABLE "deals_deal" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(140) NOT NULL, "slug" varchar(160) NOT NULL UNIQUE, "description" text NOT NULL, "external_url" varchar(600) NOT NULL, "price" decimal NOT NULL, "reference_price" decimal NULL, "currency" varchar(3) NOT NULL, "shipping_cost" decimal NOT NULL, "status" varchar(20) NOT NULL, "is_cross_border" bool NOT NULL, "language" varchar(5) NOT NULL, "starts_at" datetime NOT NULL, "ends_at" datetime NULL, "published_at" datetime NULL, "temperature" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "deleted_at" datetime NULL, "category_id" char(32) NOT NULL REFERENCES "catalog_category" ("id") DEFERRABLE INITIALLY DEFERRED, "merchant_id" char(32) NOT NULL REFERENCES "catalog_merchant" ("id") DEFERRABLE INITIALLY DEFERRED, "submitted_by_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "image_url" varchar(800) NOT NULL, "image" varchar(100) NOT NULL, "availability" varchar(10) NOT NULL, "promo_code" varchar(40) NOT NULL, "alerts_dispatched_at" datetime NULL, CONSTRAINT "deal_price_non_negative" CHECK ("price" >= '0'), CONSTRAINT "deal_shipping_non_negative" CHECK ("shipping_cost" >= '0'), CONSTRAINT "deal_reference_price_above_price" CHECK (("reference_price" IS NULL OR "reference_price" > ("price"))), CONSTRAINT "deal_ends_after_start" CHECK (("ends_at" IS NULL OR "ends_at" > ("starts_at"))), CONSTRAINT "deal_published_requires_date" CHECK ((NOT ("status" = 'published') OR "published_at" IS NOT NULL)));
CREATE TABLE "deals_dealimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "image_url" varchar(800) NOT NULL, "position" smallint unsigned NOT NULL CHECK ("position" >= 0), "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "dealimage_has_source" CHECK ((NOT ("image" = '') OR NOT ("image_url" = ''))));
CREATE TABLE "deals_dealtranslation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(5) NOT NULL, "title" varchar(140) NOT NULL, "description" text NOT NULL, "is_machine_translated" bool NOT NULL, "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_deal_language" UNIQUE ("deal_id", "language"));
CREATE TABLE "deals_pricepoint" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "price" decimal NOT NULL, "source" varchar(10) NOT NULL, "recorded_at" datetime NOT NULL, "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "pricepoint_price_positive" CHECK ("price" >= '0'));
CREATE TABLE "deals_vote" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "value" smallint NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "deal_id" char(32) NOT NULL REFERENCES "deals_deal" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_vote_per_user_deal" UNIQUE ("deal_id", "user_id"), CONSTRAINT "vote_value_is_minus_one_or_one" CHECK ("value" IN (-1, 1)));
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
