CREATE TABLE "payments_payment" ("id" char(32) NOT NULL PRIMARY KEY, "reference" varchar(30) NOT NULL UNIQUE, "amount" decimal NOT NULL, "vat_amount" decimal NOT NULL, "currency" varchar(3) NOT NULL, "status" varchar(20) NOT NULL, "gateway" varchar(30) NOT NULL, "gateway_reference" varchar(120) NOT NULL UNIQUE, "card_last4" varchar(4) NOT NULL, "card_brand" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "settled_at" datetime NULL, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "plan_id" char(32) NOT NULL REFERENCES "payments_plan" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "payment_amount_non_negative" CHECK ("amount" >= '0'), CONSTRAINT "payment_vat_within_amount" CHECK (("vat_amount" >= '0' AND "vat_amount" <= ("amount"))), CONSTRAINT "payment_succeeded_requires_settled_at" CHECK ((NOT ("status" = 'succeeded') OR "settled_at" IS NOT NULL)));
CREATE TABLE "payments_plan" ("id" char(32) NOT NULL PRIMARY KEY, "code" varchar(30) NOT NULL UNIQUE, "name_fr" varchar(80) NOT NULL, "name_nl" varchar(80) NOT NULL, "name_de" varchar(80) NOT NULL, "price" decimal NOT NULL, "vat_rate" decimal NOT NULL, "duration_days" smallint unsigned NOT NULL CHECK ("duration_days" >= 0), "is_active" bool NOT NULL, CONSTRAINT "plan_price_non_negative" CHECK ("price" >= '0'), CONSTRAINT "plan_duration_positive" CHECK ("duration_days" > 0));
CREATE TABLE "payments_subscription" ("id" char(32) NOT NULL PRIMARY KEY, "status" varchar(20) NOT NULL, "started_at" datetime NOT NULL, "ends_at" datetime NOT NULL, "cancelled_at" datetime NULL, "payment_id" char(32) NOT NULL UNIQUE REFERENCES "payments_payment" ("id") DEFERRABLE INITIALLY DEFERRED, "plan_id" char(32) NOT NULL REFERENCES "payments_plan" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "subscription_ends_after_start" CHECK ("ends_at" > ("started_at")));
