INSERT INTO "deals_dealtranslation" VALUES(1,'nl','Tv Philips Ambilight 43" PUS8001 (2026) voor 349 € in plaats van 449 €','Led-tv van 43 inch met Ambilight, model 2026, door Coolblue gekozen als ideale tv voor een kleine kamer (kijkafstand 2 tot 2,5 m). 22 % korting op de doorstreepte prijs. Morgen geleverd bij bestelling voor 23.59 uur, of afhalen in een Coolblue-winkel.',0,'7848ec990bfc45528ae08d8fbe054777');
INSERT INTO "deals_dealtranslation" VALUES(2,'de','TV Philips Ambilight 43" PUS8001 (2026) für 349 € statt 449 €','43-Zoll-LED-Fernseher mit Ambilight, Modell 2026, von Coolblue als idealer Fernseher für kleine Räume empfohlen (Sitzabstand 2 bis 2,5 m). 22 % Rabatt auf den durchgestrichenen Preis. Lieferung am nächsten Tag bei Bestellung vor 23:59 Uhr oder Abholung in einer Coolblue-Filiale.',0,'7848ec990bfc45528ae08d8fbe054777');
INSERT INTO "deals_dealtranslation" VALUES(3,'nl','Steelstofzuiger Dyson V12s Detect Slim Submarine voor 419 € in plaats van 599 €','Draadloze steelstofzuiger Dyson V12s Detect Slim met Submarine-dweilkop: zuigt en dweilt harde vloeren in één beweging. 180 € korting op de doorstreepte prijs, of -30 %. Verkocht en verzonden door Coolblue.',0,'f420652cabd8450e819781b0bc57bf7a');
INSERT INTO "deals_dealtranslation" VALUES(4,'de','Akku-Staubsauger Dyson V12s Detect Slim Submarine für 419 € statt 599 €','Kabelloser Stielstaubsauger Dyson V12s Detect Slim mit Submarine-Nasswischkopf: saugt und wischt Hartböden in einem Durchgang. 180 € Rabatt auf den durchgestrichenen Preis, also -30 %. Verkauft und versandt von Coolblue.',0,'f420652cabd8450e819781b0bc57bf7a');
INSERT INTO "deals_dealtranslation" VALUES(5,'nl','Robotstofzuiger met dweilfunctie Dreame L40s Pro Ultra voor 399 €','Robotstofzuiger en dweilrobot met station, zuigkracht van 19 000 Pa. Amazon toont een doorstreepte prijs van 899 €, maar de wettelijke referentieprijs is de laagste prijs van de voorbije 30 dagen: 502,60 €. De echte korting is dus 21 %, geen 56 %. Verkocht en verzonden door Amazon.com.be (Amazon EU, Luxemburg).',0,'47ddd4babb4b48bea8e7985487ecaf64');
INSERT INTO "deals_dealtranslation" VALUES(6,'de','Saug- und Wischroboter Dreame L40s Pro Ultra für 399 €','Saug- und Wischroboter mit Station, Saugleistung 19 000 Pa. Amazon zeigt einen durchgestrichenen Preis von 899 €, der gesetzliche Referenzpreis ist jedoch der niedrigste Preis der letzten 30 Tage: 502,60 €. Der echte Rabatt beträgt also 21 %, nicht 56 %. Verkauft und versandt von Amazon.com.be (Amazon EU, Luxemburg).',0,'47ddd4babb4b48bea8e7985487ecaf64');
INSERT INTO "deals_dealtranslation" VALUES(7,'nl','Samsung Galaxy A57 128 GB voor 9 € met een mobiel abonnement van Proximus','De smartphone kost 9 € in plaats van 549,99 €, op voorwaarde dat je 24 maanden een mobiel abonnement met een DataPhone-optie neemt (bijvoorbeeld een abonnement vanaf 15 € met de optie DataPhone 1,5 GB aan 15 €/maand). Aanbod geldig tot 3 januari 2027 voor nieuwe klanten en bestaande gsm-klanten. Reken het over twee jaar uit voor je tekent.',0,'595d99fff1c74f8881d40ca75cb9583e');
INSERT INTO "deals_dealtranslation" VALUES(8,'de','Samsung Galaxy A57 128 GB für 9 € mit einem Proximus-Mobilfunkvertrag','Das Smartphone kostet 9 € statt 549,99 €, sofern man 24 Monate lang einen Mobilfunkvertrag mit DataPhone-Option abschließt (zum Beispiel einen Tarif ab 15 € mit der Option DataPhone 1,5 GB für 15 €/Monat). Angebot gültig bis 3. Januar 2027 für Neukunden und bestehende Mobilfunkkunden. Vor der Unterschrift die Kosten über zwei Jahre berechnen.',0,'595d99fff1c74f8881d40ca75cb9583e');
INSERT INTO "deals_dealtranslation" VALUES(9,'nl','Chromebook Lenovo IdeaPad Slim 3 14 inch voor 279 € in plaats van 369 €','Chromebook Lenovo IdeaPad Slim 3 van 14 inch (referentie 14M868, AZERTY-toetsenbord). Met ChromeOS, geschikt voor studie en online kantoorwerk. 90 € korting op de doorstreepte prijs, of -24 %.',0,'1f0b57992b674c4aacfdcd9cf1b78aa6');
INSERT INTO "deals_dealtranslation" VALUES(10,'de','Chromebook Lenovo IdeaPad Slim 3 14 Zoll für 279 € statt 369 €','Chromebook Lenovo IdeaPad Slim 3 mit 14 Zoll (Referenz 14M868, AZERTY-Tastatur). Mit ChromeOS, geeignet für Studium und Online-Büroarbeit. 90 € Rabatt auf den durchgestrichenen Preis, also -24 %.',0,'1f0b57992b674c4aacfdcd9cf1b78aa6');
INSERT INTO "deals_dealtranslation" VALUES(11,'nl','Wasmachine AEG LF62CB86 ProSense voor 499 € in plaats van 599 €','Wasmachine AEG 6000-serie ProSense, die de duur en de hoeveelheid water aanpast aan het gewicht van de was. 100 € korting op de doorstreepte prijs, of -17 %.',0,'8418f10d0c544b559e6e9962b6288a73');
INSERT INTO "deals_dealtranslation" VALUES(12,'de','Waschmaschine AEG LF62CB86 ProSense für 499 € statt 599 €','Waschmaschine AEG Serie 6000 ProSense, die Dauer und Wassermenge an das Gewicht der Wäsche anpasst. 100 € Rabatt auf den durchgestrichenen Preis, also -17 %.',0,'8418f10d0c544b559e6e9962b6288a73');
INSERT INTO "deals_dealtranslation" VALUES(13,'nl','Blauwe bosbessen Delhaize 300 g voor 2,99 € in plaats van 5,49 €','Schaaltje van 300 g bosbessen in promotie in de Delhaize-winkels en in de webshop: 9,97 €/kg in plaats van 18,30 €/kg. Promotie van de week, zolang de voorraad strekt.',0,'89a030e4922b4b8d998215a7e57101b2');
INSERT INTO "deals_dealtranslation" VALUES(14,'de','Blaubeeren Delhaize 300 g für 2,99 € statt 5,49 €','Schale mit 300 g Heidelbeeren im Angebot in den Delhaize-Filialen und im Onlineshop: 9,97 €/kg statt 18,30 €/kg. Angebot der Woche, solange der Vorrat reicht.',0,'89a030e4922b4b8d998215a7e57101b2');
INSERT INTO "deals_dealtranslation" VALUES(15,'nl','Jeans Levi''s 501 Original Fit heren vanaf 50 €','De originele 501 met rechte pijp, verkocht door Amazon.com.be. De prijs van 50 € geldt voor bepaalde maten en kleuren; Amazon vermeldt een adviesprijs van 110 €, wat geen referentieprijs is in de zin van de Belgische wet: er wordt hier dus geen korting aangekondigd.',0,'91976df7f8f041f1993859a38045b63e');
INSERT INTO "deals_dealtranslation" VALUES(16,'de','Jeans Levi''s 501 Original Fit Herren ab 50 €','Die originale 501 mit geradem Schnitt, verkauft von Amazon.com.be. Der Preis von 50 € gilt für bestimmte Größen und Farben; Amazon nennt eine unverbindliche Preisempfehlung von 110 €, die kein Referenzpreis im Sinne des belgischen Rechts ist: Hier wird daher kein Rabatt angekündigt.',0,'91976df7f8f041f1993859a38045b63e');
INSERT INTO "deals_dealtranslation" VALUES(17,'nl','Tv TCL QD Mini-LED 55" C69K Pro (2026) voor 599 € in plaats van 699 €','Mini-led-tv van 55 inch, model 2026, door Coolblue-klanten beoordeeld met 9,6/10. Aanbevolen kijkafstand: 2,5 tot 3 meter. 100 € korting op de doorstreepte prijs, of -14 %.',0,'1f152c11406c449f99991803447c5952');
INSERT INTO "deals_dealtranslation" VALUES(18,'de','TV TCL QD Mini-LED 55" C69K Pro (2026) für 599 € statt 699 €','Mini-LED-Fernseher mit 55 Zoll, Modell 2026, von Coolblue-Kunden mit 9,6/10 bewertet. Empfohlener Sitzabstand: 2,5 bis 3 Meter. 100 € Rabatt auf den durchgestrichenen Preis, also -14 %.',0,'1f152c11406c449f99991803447c5952');
INSERT INTO "deals_dealtranslation" VALUES(19,'nl','Tv Philips Ambilight 50" PQS9001 QLED (2026) voor 699 € in plaats van 899 €','QLED-tv van 50 inch met Ambilight en 100 Hz-scherm, model 2026. 200 € korting op de doorstreepte prijs, of -22 %.',0,'a346020702f447e5a6eaa911332e299b');
INSERT INTO "deals_dealtranslation" VALUES(20,'de','TV Philips Ambilight 50" PQS9001 QLED (2026) für 699 € statt 899 €','QLED-Fernseher mit 50 Zoll, Ambilight und 100-Hz-Panel, Modell 2026. 200 € Rabatt auf den durchgestrichenen Preis, also -22 %.',0,'a346020702f447e5a6eaa911332e299b');
